#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c;
    cin >> a >> b >> c;

    long long weeks = min({a / 3, b / 2, c / 2});
    a -= weeks * 3;
    b -= weeks * 2;
    c -= weeks * 2;

    const int schedule[7] = {0, 1, 2, 0, 2, 1, 0};
    long long extra = 0;

    for (int start = 0; start < 7; ++start) {
        long long food[3] = {a, b, c};
        long long days = 0;

        while (food[schedule[(start + days) % 7]] > 0) {
            --food[schedule[(start + days) % 7]];
            ++days;
        }

        extra = max(extra, days);
    }

    cout << weeks * 7 + extra << '\n';
    return 0;
}

